-- Go-live stages and client controls (ARCHITECTURE v0.12 §5.5, §10.9, §11.5): a client agent's
-- `stage` (bench → trial → signoff → live), how it got there (`stage_state`: the trial's start and
-- minimums, the sign-off ask, skips) and who paused it (`pause`: the client, the operator or the
-- system). Nullable columns or columns with defaults, so the previous Worker keeps working: it never
-- reads them, and a client agent it creates is started at `bench` by the trigger below, so the
-- checks pass. Generated by drizzle-kit; the trigger and the backfill are hand-written, and the
-- backfill runs before the check that client agents have a stage.
ALTER TABLE "agent" ADD COLUMN "stage" text;--> statement-breakpoint
ALTER TABLE "agent" ADD COLUMN "stage_state" jsonb DEFAULT '{}'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "agent" ADD COLUMN "pause" jsonb;--> statement-breakpoint
ALTER TABLE "agent" ADD CONSTRAINT "agent_stage_check" CHECK ("agent"."stage" is null or "agent"."stage" in ('bench', 'trial', 'signoff', 'live'));--> statement-breakpoint

-- DECISION: a client agent never has a null stage. A new one starts at `bench` (§10.9), whichever
-- Worker inserts it, so the code never has to guess what null means; templates keep null.
CREATE OR REPLACE FUNCTION agent_stage_default() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.kind = 'client' AND NEW.stage IS NULL THEN
    NEW.stage := 'bench';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER agent_stage_default BEFORE INSERT ON agent
  FOR EACH ROW EXECUTE FUNCTION agent_stage_default();
--> statement-breakpoint

-- Backfill (§10.9: agents live before v0.12 are live): a client agent that has run live (active,
-- paused or retired) is `live`; every other client agent (draft, testing, never activated) and
-- every template's test copy is `bench`. Test copies are never activated and never go live.
UPDATE agent SET stage = CASE
    WHEN run_status IN ('active', 'paused', 'retired') AND NOT test_copy THEN 'live'
    ELSE 'bench'
  END
  WHERE kind = 'client' AND stage IS NULL;
--> statement-breakpoint
ALTER TABLE "agent" ADD CONSTRAINT "agent_stage_kind_check" CHECK (("agent"."kind" = 'client') = ("agent"."stage" is not null));
